298  /// performs several alias changes in an atomic fashion
299  async fn update_aliases(&self, operation: ChangeAliasesOperation) -> Result<bool, StorageError> {
305      let collection_lock = self.collections.write().await;
306      let mut alias_lock = self.alias_persistence.write().await;
307      for action in operation.actions {
308          match action {
309              AliasOperations::CreateAlias(CreateAliasOperation { create_alias: CreateAlias { collection_name, alias_name } }) => {
316                  collection_lock.validate_collection_exists(&collection_name)?;   // -> NotFound -> HTTP 404
317                  collection_lock.validate_collection_not_exists(&alias_name)?;
319                  alias_lock.insert(alias_name, collection_name)?;
320              }
321              AliasOperations::DeleteAlias(DeleteAliasOperation { delete_alias: DeleteAlias { alias_name } }) => {
324                  alias_lock.remove(&alias_name)?;   // NO existence validation
325              }
326              AliasOperations::RenameAlias(RenameAliasOperation { rename_alias: RenameAlias { old_alias_name, new_alias_name } }) => {
333                  alias_lock.rename_alias(&old_alias_name, new_alias_name)?;   // -> validates old exists
334              }
336          }
337      }
338      Ok(true)

